  "verses": [
    {
      "chapter": 4,
      "text_ar": "الآن تعال معي فننهب كل ما تبقى في منزله.",
      "verse": 16
    },
    {
      "chapter": 4,
      "text_ar": "فأجابوا وقالوا له: \"له سبعة بنين وثلاث بنات.",
      "verse": 17
    },
    {
      "chapter": 4,
      "text_ar": "احذر لئلا يهربوا إلى أراضٍ أخرى فيصيروا طغاة علينا ثم يأتوا علينا بقوة ويقتلونا.\"",
      "verse": 18
    },
    {
      "chapter": 4,
      "text_ar": "فقال: لا تخافوا البتة. إن قطيعه وثروته قد أهلكتهما بالنار، وما تبقى فقد أسرته، وها أنا أقتل أولاده.\"",
      "verse": 19
    },
    {
      "chapter": 4,
      "text_ar": "ولما تكلم هكذا، ذهب وأسقط البيت على أولادي فقتلهم.",
      "verse": 20
    }
  ],
  "book_code": "TJOB"
}
